int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int noblock = flags & MSG_DONTWAIT;
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & ~(MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (skb->len > size) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
    } else {
        copied = skb->len;
    }

    if (copy_to_iter(skb->data, copied, msg->msg_iter) != copied) {
        kfree_skb(skb);
        return -EFAULT;
    }

    if (!(flags & MSG_PEEK)) {
        sk->sk_forward_alloc -= skb->truesize;
        sock_release_data(skb);
    }

    return copied;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state != TCP_ESTABLISHED) {
        return -ENOTCONN;
    }

    if (flags & ~(MSG_DONTWAIT | MSG_PEEK | MSG_WAITALL)) {
        return -EINVAL;
    }

    ret = skb_recv_datagram(sk, flags, &msg->msg_data, size);
    if (ret < 0) {
        return ret;
    }

    if (ret > (int)size) {
        if (!(flags & MSG_TRUNC)) {
            ret = size;
        }
    }

    if (!(flags & MSG_PEEK)) {
        sock_update_mem(sk, -ret);
    }

    kfree_skb(msg->msg_data);
    return ret;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (!sk)
        return -EINVAL;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (skb->len > size) {
        if (flags & MSG_TRUNC) {
            copied = skb->len;
        } else {
            copied = size;
        }
    } else {
        copied = skb->len;
    }

    err = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    if (!(flags & MSG_PEEK)) {
        skb_pull(skb, copied);
        if (skb->len == 0)
            kfree_skb(skb);
        else
            skb_queue_head(&sk->sk_receive_queue, skb);
    }

    return copied;
}

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock,
                                struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state != TCP_ESTABLISHED)
        return -ENOTCONN;

    if (flags & ~(MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    skb = skb_recv_datagram(sk, flags, flags & MSG_DONTWAIT ? 1 : 0, &copied);
    if (!skb)
        return (copied < 0 ? copied : 0);

    if (size < skb->len) {
        if (msg->msg_flags & MSG_TRUNC)
            copied = skb->len;
        else
            copied = size;
    } else {
        copied = skb->len;
    }

    if (memcpy_to_msg(msg, skb->data, copied) < 0)
        return -EFAULT;

    if (!(flags & MSG_PEEK))
        skb_pull(skb, copied);

    if (copied)
        sock_put sock;

    kfree_skb(skb);
    return copied;
}
